//!
//! Added in this fork.
//!
//! Source geometry: https://github.com/ppatrzyk/polska-geojson
//! (`wojewodztwa/wojewodztwa-min.geojson`), MIT License,
//! Copyright (c) 2019 Piotr Patrzyk. Underlying administrative
//! boundaries originate from GUGiK PRG open data
//! (Panstwowy Rejestr Granic, public-sector open data).
//!
//! Conversion: lon/lat -> spherical-mercator projection, fitted into a
//! 600x560 viewBox, coordinates rounded to integers (all features share
//! one rounding grid, so adjacent voivodeships keep coincident borders).
//! Label anchors are bounding-box centres of each voivodeship's largest
//! polygon.

/// SVG viewBox width of the generated map.
pub const MAP_VIEWBOX_WIDTH: u32 = 600;
/// SVG viewBox height of the generated map.
pub const MAP_VIEWBOX_HEIGHT: u32 = 560;

/// One entry per voivodeship: `region_code` first segment, Polish
/// display name, label anchor (x, y) and SVG path data.
pub struct VoivodeshipPath {
    pub code: &'static str,
    pub name: &'static str,
    pub label_x: i32,
    pub label_y: i32,
    pub path: &'static str,
}

